import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"3、【屯】 震下坎上","description":"溫公易說 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"溫公易說 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"classics/wengong/004.md","filePath":"classics/wengong/004.md"}'),l={name:"classics/wengong/004.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><h3 id="彖曰-屯剛柔始交而難生-動乎險中-大亨貞。雷雨之動-滿盈天造草昧-宜建侯而不寜。" tabindex="-1">彖曰：屯剛柔始交而難生，動乎險中，大亨貞。雷雨之動，滿盈天造草昧，宜建侯而不寜。 <a class="header-anchor" href="#彖曰-屯剛柔始交而難生-動乎險中-大亨貞。雷雨之動-滿盈天造草昧-宜建侯而不寜。" aria-label="Permalink to “彖曰：屯剛柔始交而難生，動乎險中，大亨貞。雷雨之動，滿盈天造草昧，宜建侯而不寜。”">​</a></h3><h3 id="象曰-雲雷屯-君子以經綸。" tabindex="-1">象曰：雲雷屯，君子以經綸。 <a class="header-anchor" href="#象曰-雲雷屯-君子以經綸。" aria-label="Permalink to “象曰：雲雷屯，君子以經綸。”">​</a></h3><p>屯者何？草木之始生也，貫地而出。屯然其難也，象曰君子以經綸。經綸者何？猶雲綱紀也。屯者結之不解者也，結而不解則亂，亂而不緝則窮。是以君子設綱布紀，以緝其亂，解其結，然後物得其分，事得其序，治屯之道也。</p><h3 id="初九-盤桓-利居貞-利建侯。-象曰-雖盤桓-志行正也。以貴下賤-大得民也。" tabindex="-1">初九：盤桓，利居貞，利建侯。 象曰：雖盤桓，志行正也。以貴下賤，大得民也。 <a class="header-anchor" href="#初九-盤桓-利居貞-利建侯。-象曰-雖盤桓-志行正也。以貴下賤-大得民也。" aria-label="Permalink to “初九：盤桓，利居貞，利建侯。 象曰：雖盤桓，志行正也。以貴下賤，大得民也。”">​</a></h3><p>屯初九盤桓者何？治屯之道不可遽也。利居貞者何？治之不正愈以亂之也。利建侯者何？建侯所以治其綱也。治其綱百目張，夫又何亂之不緝，何結之不解乎？此之謂經綸之道也。</p><h3 id="六二-屯如邅如-乘馬班如-匪-婚媾女子-貞不字-十年乃字。-象曰-六二之難-乘剛也。十年乃字-反常也。" tabindex="-1">六二：屯如邅如，乘馬班如，匪？婚媾女子，貞不字，十年乃字。 象曰：六二之難，乘剛也。十年乃字，反常也。 <a class="header-anchor" href="#六二-屯如邅如-乘馬班如-匪-婚媾女子-貞不字-十年乃字。-象曰-六二之難-乘剛也。十年乃字-反常也。" aria-label="Permalink to “六二：屯如邅如，乘馬班如，匪？婚媾女子，貞不字，十年乃字。 象曰：六二之難，乘剛也。十年乃字，反常也。”">​</a></h3><p>人臣之道，患不正也，患不一也。茍一而正，通可必也。十年之屯，猶一日也。</p><h3 id="六三-即鹿無虞-惟入於林中-君子幾不如舍-往吝。-象曰-即鹿無虞-以從禽也。君子舍之-往吝窮也。" tabindex="-1">六三：即鹿無虞，惟入於林中，君子幾不如舍，往吝。 象曰：即鹿無虞，以從禽也。君子舍之，往吝窮也。 <a class="header-anchor" href="#六三-即鹿無虞-惟入於林中-君子幾不如舍-往吝。-象曰-即鹿無虞-以從禽也。君子舍之-往吝窮也。" aria-label="Permalink to “六三：即鹿無虞，惟入於林中，君子幾不如舍，往吝。 象曰：即鹿無虞，以從禽也。君子舍之，往吝窮也。”">​</a></h3><h3 id="六四-乘馬班如-求婚媾-往吉-無不利。-象曰-求而往-明也。" tabindex="-1">六四：乘馬班如，求婚媾，往吉，無不利。 象曰：求而往，明也。 <a class="header-anchor" href="#六四-乘馬班如-求婚媾-往吉-無不利。-象曰-求而往-明也。" aria-label="Permalink to “六四：乘馬班如，求婚媾，往吉，無不利。 象曰：求而往，明也。”">​</a></h3><h3 id="九五-屯其膏-小貞吉-大貞兇。-象曰-屯其膏-施未光也。" tabindex="-1">九五：屯其膏，小貞吉，大貞兇。 象曰：屯其膏，施未光也。 <a class="header-anchor" href="#九五-屯其膏-小貞吉-大貞兇。-象曰-屯其膏-施未光也。" aria-label="Permalink to “九五：屯其膏，小貞吉，大貞兇。 象曰：屯其膏，施未光也。”">​</a></h3><h3 id="上六-乘馬班如-泣血漣如。-象曰-泣血漣如-如何可長也。" tabindex="-1">上六：乘馬班如，泣血漣如。 象曰：泣血漣如，如何可長也。 <a class="header-anchor" href="#上六-乘馬班如-泣血漣如。-象曰-泣血漣如-如何可長也。" aria-label="Permalink to “上六：乘馬班如，泣血漣如。 象曰：泣血漣如，如何可長也。”">​</a></h3>',12)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
